#include <stdio.h>

int add(int a, int b);            // prototype

int factorial(int n) {            // recursion
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int main() {
    printf("%d %d\n", add(2, 3), factorial(5));   // 5 120
    return 0;
}

int add(int a, int b) {           // definition, matching the prototype above
    return a + b;
}
